export class RingEventQueue {
  constructor(capacity = 256) {
    this.capacity = capacity;
    this.buffer = new Array(capacity);
    this.head = 0;
    this.tail = 0;
    this.count = 0;
    for (let index = 0; index < capacity; index += 1) {
