import { EVENT, GAME_CONFIG } from '@space/GameConfig.js';
import { clamp } from '@shared/math/Math2D.js';

function syncInvaderPositions(state) {
  const { formation } = state;
  const { columns, columnPitch, rowPitch } = GAME_CONFIG.formation;
  const pool = state.invaderPool;
  let lowestY = Infinity;

  for (let index = 0; index < pool.capacity; index += 1) {
    if (!pool.isActive(index)) {
      continue;
    }
    const invader = pool.itemAt(index);
    invader.x = formation.x + (invader.column - (columns - 1) * 0.5) * columnPitch;
    invader.y = formation.y - invader.row * rowPitch;
    invader.pulse = Math.max(0, invader.pulse - 0.075);
    lowestY = Math.min(lowestY, invader.y - invader.halfHeight);
  }
  if (lowestY <= GAME_CONFIG.world.invasionLine) {
    formation.breached = true;
  }
}

export function updateFormation(state, delta) {
  const formation = state.formation;
  formation.descendedThisStep = false;
  if (formation.aliveCount <= 0) {
    return;
  }

  const aliveRatio = formation.aliveCount / formation.initialCount;
  const baseSpeed = GAME_CONFIG.formation.baseSpeed[state.campaignWave];
  const speed = baseSpeed * (1 + 1.85 * (1 - aliveRatio));
  const pool = state.invaderPool;
  let leftMost = Infinity;
  let rightMost = -Infinity;

  for (let index = 0; index < pool.capacity; index += 1) {
    if (!pool.isActive(index)) {
      continue;
    }
    const invader = pool.itemAt(index);
    leftMost = Math.min(leftMost, invader.x - invader.halfWidth);
    rightMost = Math.max(rightMost, invader.x + invader.halfWidth);
  }

  const displacement = formation.direction * speed * delta;
  if (leftMost + displacement < -GAME_CONFIG.formation.sideLimit || rightMost + displacement > GAME_CONFIG.formation.sideLimit) {
    const target = formation.direction < 0
      ? -GAME_CONFIG.formation.sideLimit - leftMost
      : GAME_CONFIG.formation.sideLimit - rightMost;
    formation.x += target;
    formation.direction *= -1;
    formation.y -= GAME_CONFIG.formation.descent;
    formation.descendedThisStep = true;
    formation.marchStep = (formation.marchStep + 1) % 4;
    state.events.push(EVENT.MARCH, formation.x, formation.y, 0, formation.marchStep, 0.18, GAME_CONFIG.colors.alien[1]);
  } else {
    formation.x += displacement;
  }

  formation.marchTimer -= delta;
  if (formation.marchTimer <= 0) {
    formation.marchTimer += Math.max(0.085, GAME_CONFIG.formation.baseMarchInterval * aliveRatio ** 1.55);
    formation.marchStep = (formation.marchStep + 1) % 4;
    state.events.push(EVENT.MARCH, formation.x, formation.y, 0, formation.marchStep, 0.08, GAME_CONFIG.colors.alien[2]);
    for (let index = 0; index < pool.capacity; index += 1) {
      if (pool.isActive(index)) {
        pool.itemAt(index).pulse = 1;
      }
    }
  }

  formation.x = clamp(formation.x, -12, 12);
  syncInvaderPositions(state);
}

import { GAME_CONFIG } from '@space/GameConfig.js';

export function awardScore(state, amount) {
  state.score += amount;
  state.highScore = Math.max(state.highScore, state.score);
  return state.score;
}

export function awardWaveBonus(state) {
  let survivingCells = 0;
  for (const cell of state.barrierCells) {
    if (cell.active) {
      survivingCells += 1;
    }
  }
  const bonus = state.campaignWave * 250 + survivingCells * 4 + state.lives * 100;
  awardScore(state, bonus);
  return bonus;
}

import { GAME_CONFIG } from '@space/GameConfig.js';

export function trySpawnUfo(state, delta) {
  if (state.ufo) {
    return;
  }
  state.ufoCooldown -= delta;
  if (state.ufoCooldown > 0) {
    return;
  }
  const probability = 1 - Math.exp(-GAME_CONFIG.ufo.spawnRate * delta);
  if (!state.rng.chance(probability)) {
    return;
  }
  const ufo = state.ufoPool.acquire();
  if (!ufo) {
    return;
  }
  ufo.active = true;
  ufo.direction = state.rng.chance(0.5) ? 1 : -1;
  ufo.x = ufo.direction > 0 ? GAME_CONFIG.world.left - 1.2 : GAME_CONFIG.world.right + 1.2;
  ufo.y = GAME_CONFIG.ufo.y;
  ufo.score = GAME_CONFIG.ufo.scoreTable[state.rng.int(0, GAME_CONFIG.ufo.scoreTable.length - 1)];
  ufo.age = 0;
  state.ufo = ufo;
}

export function updateUfo(state, delta) {
  if (!state.ufo) {
    trySpawnUfo(state, delta);
    return;
  }
  const ufo = state.ufo;
  ufo.age += delta;
  ufo.x += ufo.direction * GAME_CONFIG.ufo.speed * delta;
  if (ufo.x < GAME_CONFIG.world.left - 1.7 || ufo.x > GAME_CONFIG.world.right + 1.7) {
    state.ufoPool.release(ufo);
    state.ufo = null;
    state.ufoCooldown = GAME_CONFIG.ufo.cooldown;
  }
}

import { GAME_CONFIG } from '@space/GameConfig.js';
import { clamp, moveToward } from '@shared/math/Math2D.js';

export function updatePlayer(state, input, delta) {
  const player = state.player;
  player.previousX = player.x;
  player.fireRequested = false;
  if (!player.alive) {
    return;
  }

  player.fireCooldown = Math.max(0, player.fireCooldown - delta);
  player.invulnerability = Math.max(0, player.invulnerability - delta);
  const desiredVelocity = input.value('move') * GAME_CONFIG.player.maxSpeed;
  const acceleration = Math.abs(desiredVelocity) > Math.abs(player.velocityX)
    ? GAME_CONFIG.player.acceleration
    : GAME_CONFIG.player.braking;
  player.velocityX = moveToward(player.velocityX, desiredVelocity, acceleration * delta);
  player.x = clamp(
    player.x + player.velocityX * delta,
    GAME_CONFIG.world.left + player.halfWidth,
    GAME_CONFIG.world.right - player.halfWidth,
  );

  if (input.value('fire') && player.fireCooldown <= 0) {
    player.fireRequested = true;
    player.fireCooldown = GAME_CONFIG.player.fireCooldown;
  }
}

import { GAME_CONFIG } from '@space/GameConfig.js';
import { aabbOverlaps, circleHitsCell } from '@shared/math/Collision2D.js';

export function resetBarriers(state) {
  const { mask, width } = GAME_CONFIG.barrier;
  for (let index = 0; index < state.barrierCells.length; index += 1) {
    const cell = state.barrierCells[index];
    cell.active = mask[cell.row][cell.column] === '1';
    if (cell.column >= width) {
      cell.active = false;
    }
  }
}

export function damageBarrier(state, x, y, radius) {
  let damaged = 0;
  for (let index = 0; index < state.barrierCells.length; index += 1) {
    const cell = state.barrierCells[index];
    if (!cell.active) {
      continue;
    }
    if (circleHitsCell(x, y, radius, cell.x, cell.y, cell.halfWidth, cell.halfHeight)) {
      cell.active = false;
      damaged += 1;
    }
  }
  return damaged;
}

export function erodeBarriers(state) {
  let eroded = 0;
  const invaderPool = state.invaderPool;
  for (let invaderIndex = 0; invaderIndex < invaderPool.capacity; invaderIndex += 1) {
    if (!invaderPool.isActive(invaderIndex)) {
      continue;
    }
    const invader = invaderPool.itemAt(invaderIndex);
    for (let cellIndex = 0; cellIndex < state.barrierCells.length; cellIndex += 1) {
      const cell = state.barrierCells[cellIndex];
      if (!cell.active) {
        continue;
      }
      if (aabbOverlaps(
        invader.x - invader.halfWidth,
        invader.x + invader.halfWidth,
        invader.y - invader.halfHeight,
        invader.y + invader.halfHeight,
        cell.x - cell.halfWidth,
        cell.x + cell.halfWidth,
        cell.y - cell.halfHeight,
        cell.y + cell.halfHeight,
      )) {
        cell.active = false;
        eroded += 1;
      }
    }
  }
  return eroded;
}

import { EVENT, GAME_CONFIG } from '@space/GameConfig.js';

function initializeProjectile(projectile, owner, x, y, velocityY, radius, tint) {
  projectile.active = true;
  projectile.owner = owner;
  projectile.x = x;
  projectile.y = y;
  projectile.previousY = y;
  projectile.velocityY = velocityY;
  projectile.radius = radius;
  projectile.age = 0;
  projectile.tint = tint;
}

export function spawnPlayerBeam(state) {
  if (!state.player.alive || state.playerProjectilePool.activeCount >= GAME_CONFIG.player.activeBeamLimit) {
    return false;
  }
  const projectile = state.playerProjectilePool.acquire();
  if (!projectile) {
    return false;
  }
  initializeProjectile(
    projectile,
    'player',
    state.player.x,
    state.player.y + state.player.halfHeight + 0.14,
    GAME_CONFIG.projectile.playerSpeed,
    GAME_CONFIG.projectile.playerRadius,
    GAME_CONFIG.colors.player,
  );
  state.events.push(EVENT.SHOT_PLAYER, projectile.x, projectile.y, 0.1, 0, 0.08, projectile.tint);
  return true;
}

function chooseBottomInvader(state) {
  const startColumn = state.rng.int(0, GAME_CONFIG.formation.columns - 1);
  const pool = state.invaderPool;
  for (let offset = 0; offset < GAME_CONFIG.formation.columns; offset += 1) {
    const column = (startColumn + offset) % GAME_CONFIG.formation.columns;
    let best = null;
    for (let index = 0; index < pool.capacity; index += 1) {
      if (!pool.isActive(index)) {
        continue;
      }
      const invader = pool.itemAt(index);
      if (invader.column === column && (!best || invader.row > best.row)) {
        best = invader;
      }
    }
    if (best) {
      return best;
    }
  }
  return null;
}

export function spawnAlienBeam(state) {
  const source = chooseBottomInvader(state);
  const projectile = source ? state.alienProjectilePool.acquire() : null;
  if (!projectile) {
    return false;
  }
  initializeProjectile(
    projectile,
    'alien',
    source.x,
    source.y - source.halfHeight - 0.16,
    -(GAME_CONFIG.projectile.alienBaseSpeed + GAME_CONFIG.projectile.alienWaveSpeed * state.campaignWave),
    GAME_CONFIG.projectile.alienRadius,
    GAME_CONFIG.colors.alien[source.rank],
  );
  state.events.push(EVENT.SHOT_ALIEN, projectile.x, projectile.y, 0.08, 0, 0.06, projectile.tint);
  return true;
}

function updatePool(pool, delta) {
  for (let index = 0; index < pool.capacity; index += 1) {
    if (!pool.isActive(index)) {
      continue;
    }
    const projectile = pool.itemAt(index);
    projectile.previousY = projectile.y;
    projectile.y += projectile.velocityY * delta;
    projectile.age += delta;
    if (
      projectile.y < GAME_CONFIG.world.bottom - GAME_CONFIG.projectile.boundsPadding
      || projectile.y > GAME_CONFIG.world.top + GAME_CONFIG.projectile.boundsPadding
    ) {
      pool.release(projectile);
    }
  }
}

export function updateProjectiles(state, delta) {
  updatePool(state.playerProjectilePool, delta);
  updatePool(state.alienProjectilePool, delta);
}

