  }

  const alienPool = state.alienProjectilePool;
  for (let index = 0; index < alienPool.capacity; index += 1) {
    if (alienPool.isActive(index)) {
      resolveAlienProjectile(state, alienPool.itemAt(index));
    }
  }
}

