.overlay-kicker {
  margin: 0 0 11px;
  color: var(--magenta);
}

.overlay-heading {
  margin: 0;
  color: var(--cyan);
  font-size: clamp(32px, 8vw, 59px);
  line-height: 0.9;
  text-shadow: 0 0 22px rgba(73, 255, 241, 0.7);
}

.overlay-message {
  margin: 19px auto 25px;
  max-width: 35ch;
  color: #cadced;
  font-size: 13px;
  line-height: 1.65;
  letter-spacing: 0.035em;
}

.primary-action,
.secondary-action {
  display: block;
  width: 100%;
  padding: 12px 16px;
  border-radius: 3px;
  font-weight: 800;
  font-size: 11px;
}

.primary-action {
  background: linear-gradient(90deg, rgba(12, 153, 179, 0.82), rgba(42, 75, 172, 0.82));
  box-shadow: 0 0 24px rgba(73, 255, 241, 0.28);
}

.secondary-action {
  margin-top: 9px;
  border-color: rgba(255, 76, 184, 0.52);
  color: #ffc4e5;
}

.primary-action:hover,
.primary-action:focus-visible,
.secondary-action:hover,
.secondary-action:focus-visible {
  transform: translateY(-2px);
  box-shadow: 0 0 26px rgba(73, 255, 241, 0.58);
  outline: none;
}

.score-layer {
  position: absolute;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
}

.score-float {
  position: absolute;
  top: 0;
  left: 0;
  font-size: 16px;
  font-weight: 900;
  letter-spacing: 0.04em;
  text-shadow: 0 0 12px currentColor;
  will-change: transform, opacity;
}

.telemetry {
  position: absolute;
  right: 14px;
  bottom: 12px;
  z-index: 4;
  margin: 0;
  padding: 8px;
  border: 1px solid rgba(73, 255, 241, 0.36);
  background: rgba(0, 0, 0, 0.6);
  color: #a6fff5;
  font: 11px/1.35 monospace;
  pointer-events: none;
}

@media (max-width: 560px) {
  .hud-status {
    min-width: 145px;
    padding: 8px 10px;
  }

  .hud-value {
    font-size: 18px;
  }

  .hud-actions {
    top: 59px;
  }

  .hud-icon {
    font-size: 8px;
    padding: 6px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .overlay,
  .controls-hint,
  .hud-icon,
  .primary-action,
  .secondary-action {
    transition: none;
  }
}

