import { describe, expect, it } from 'vitest';
import { GAME_CONFIG } from '../../src/Space_Invaders/GameConfig.js';
import { createGameState } from '../../src/Space_Invaders/simulation/GameState.js';
import { spawnPlayerBeam, updateProjectiles } from '../../src/Space_Invaders/simulation/ProjectileSystem.js';

describe('projectile pooling', () => {
  it('spawns a pooled player beam and advances it at configured speed', () => {
    const state = createGameState();
    const startY = state.player.y + state.player.halfHeight + 0.14;
    expect(spawnPlayerBeam(state)).toBe(true);
    const beam = state.playerProjectilePool.itemAt(0);
    updateProjectiles(state, GAME_CONFIG.fixedStep);
    expect(beam.y).toBeCloseTo(startY + GAME_CONFIG.projectile.playerSpeed * GAME_CONFIG.fixedStep, 6);
    expect(beam.trailPending).toBe(true);
  });
});

import { describe, expect, it } from 'vitest';
import { createGameState } from '../../src/Space_Invaders/simulation/GameState.js';
import { resolveCollisions } from '../../src/Space_Invaders/simulation/CollisionSystem.js';
import { beginWave } from '../../src/Space_Invaders/simulation/WaveDirector.js';

describe('projectile collisions', () => {
  it('uses a swept player beam to defeat an invader and release the beam', () => {
    const state = createGameState();
    beginWave(state, 1);
    const invader = state.invaderPool.itemAt(0);
    const beam = state.playerProjectilePool.acquire();
    beam.active = true;
    beam.owner = 'player';
    beam.x = invader.x;
    beam.previousY = invader.y - 1;
    beam.y = invader.y + 1;
    beam.radius = 0.1;
    beam.tint = 0xffffff;

    resolveCollisions(state);

    expect(state.invaderPool.activeCount).toBe(54);
    expect(state.playerProjectilePool.activeCount).toBe(0);
    expect(state.score).toBe(30);
  });
});

import { describe, expect, it } from 'vitest';
import { ObjectPool } from '../../src/shared/core/ObjectPool.js';

describe('ObjectPool', () => {
  it('reuses a fixed slot without exceeding capacity', () => {
    const pool = new ObjectPool(2, () => ({ value: 0 }), (item) => {
      item.value = 0;
    });
    const first = pool.acquire();
    const second = pool.acquire();
    expect(pool.acquire()).toBeNull();
    first.value = 99;
    expect(pool.release(first)).toBe(true);
    const recycled = pool.acquire();
    expect(recycled).toBe(first);
    expect(recycled.value).toBe(0);
    expect(pool.activeCount).toBe(2);
    expect(pool.release(second)).toBe(true);
  });
});

